<?php
ob_start();require '/wordpress/wp-load.php';wp_set_current_user(1);$n=0;function check($ok,$label){global $n;if(!$ok){throw new Exception('FAIL: '.$label);}echo 'PASS: '.$label."\n";$n++;}
check(wp_is_block_theme(),'Real block theme active');check(get_option('blog_public')==='0'||get_option('blog_public')===0,'Demo indexing disabled');check(count(get_pages())>=14,'All core pages and templates created');check(is_wp_error(aurelia_seed()),'Setup protects existing pages');foreach(array('home','about','services','booking','team','gallery','reviews','journal','contact','faq','policies','thank-you') as $slug){$p=get_page_by_path($slug);check($p&&has_blocks($p->post_content),'Editable blocks: '.$slug);}
$c=au_config();check(count($c['services'])===6,'Six services configured');$tz=new DateTimeZone($c['timezone']);$date=(new DateTimeImmutable('next monday +1 week',$tz))->format('Y-m-d');$sunday=(new DateTimeImmutable('next sunday',$tz))->format('Y-m-d');check(count(au_slots('signature','ava',$date))>0,'Future provider availability');check(au_slots('signature','ava',$sunday)===array(),'Sunday closed');check(au_slots('signature','noah',$date)===array(),'Incompatible provider rejected');check(au_slots('signature','ava','2026-02-30')===array(),'Invalid calendar date rejected');check(au_slots('signature','ava','2020-01-01')===array(),'Past date rejected');check(au_slots('signature','ava','2035-01-01')===array(),'Booking horizon enforced');
$c['closed_dates']=array($date);update_option('au_config',$c);check(au_slots('signature','ava',$date)===array(),'Unavailable date respected');$c['closed_dates']=array();update_option('au_config',$c);
check(au_time('2027-01-15','09:00')->format('P')==='-05:00','Miami winter timezone');check(au_time('2027-07-15','09:00')->format('P')==='-04:00','Miami summer timezone');
$valid=array('name'=>'Demo Person','email'=>'demo@example.test','phone'=>'+1 305 555 0142','service'=>'signature','provider'=>'ava','date'=>$date,'time'=>'09:00','notes'=>'Fictional test only','consent'=>'yes','website'=>'');foreach(array(array('email','bad'),array('consent',''),array('phone','invalid'),array('name','A')) as $bad){$v=$valid;$v[$bad[0]]=$bad[1];check(is_wp_error(au_contact_data($v)),'Invalid '.$bad[0].' rejected');}
function req($d,$route='/aurelia/v1/book'){$r=new WP_REST_Request('POST',$route);$r->set_header('Content-Type','application/json');$r->set_body(wp_json_encode($d));return $r;}
function challengeData($d){$stamp=time()-4;$ch=wp_generate_password(32,false,false);return array_merge($d,array('stamp'=>$stamp,'challenge'=>$ch,'signature'=>hash_hmac('sha256',$stamp.'.'.$ch,wp_salt('nonce'))));}
check(is_wp_error(au_book(req(challengeData($valid)))),'Demo blocks server collection');update_option('au_settings',array('demo'=>0,'test'=>1,'recipient'=>'test@example.test','privacy'=>'https://example.com/privacy','retention'=>120));$mail=array();add_filter('pre_wp_mail',function($return,$attrs)use(&$mail){$mail[]=$attrs;return true;},10,2);
$data=challengeData($valid);$result=au_book(req($data));check($result instanceof WP_REST_Response&&$result->get_status()===201,'Valid reservation saved');$ref=$result->get_data()['reference'];$posts=get_posts(array('post_type'=>'au_appointment','post_status'=>'private','numberposts'=>1));$id=$posts[0]->ID;check(count($posts)===1,'Private appointment stored');check(!in_array('09:15',au_slots('hydrating','ava',$date),true),'Overlapping duration unavailable');check(is_wp_error(au_book(req(challengeData($valid)))),'Second booking rejected');check(is_wp_error(au_book(req($data))),'Repeated submission rejected');check(get_post_meta($id,'_au_mail',true)==='accepted','Mail acceptance recorded');check($mail[0]['to']==='test@example.test','Test mode routes notification to test inbox');check((bool)wp_next_scheduled('au_reminder',array($id)),'Reminder scheduled');
$stamp=au_time($date,'09:00')->getTimestamp();check(au_lock('ava',$stamp,60,'OTHER')===false,'Atomic lock rejects occupied interval');$token='known-test-token';update_post_meta($id,'_au_token_hash',hash('sha256',$token));$m=array('reference'=>$ref,'token'=>'bad','action'=>'cancel');check(is_wp_error(au_manage(req($m))),'Invalid management token rejected');$m['token']=$token;$m['action']='reschedule';$m['date']=$date;$m['time']='11:00';$r=au_manage(req($m));check(!is_wp_error($r),'Rescheduling succeeds');check(in_array('09:00',au_slots('signature','ava',$date),true),'Rescheduling releases old interval');check(!in_array('11:15',au_slots('signature','ava',$date),true),'Rescheduling reserves new interval');$m['action']='cancel';check(!is_wp_error(au_manage(req($m))),'Cancellation succeeds');check(in_array('11:00',au_slots('signature','ava',$date),true),'Cancellation releases interval');check(is_wp_error(au_manage(req($m))),'Cancelled appointment cannot be cancelled again');
$lead=challengeData(array_merge($valid,array('message'=>'A fictional general inquiry for testing.','category'=>'General question')));$r=au_lead(req($lead));check($r instanceof WP_REST_Response,'Inquiry saved');$leads=get_posts(array('post_type'=>'au_lead','post_status'=>'private','numberposts'=>1));check(get_post_meta($leads[0]->ID,'_au_data',true)['status']==='New','Lead status initialized');check(!get_post_type_object('au_appointment')->show_in_rest,'No public appointment REST exposure');wp_set_current_user(0);check(!current_user_can('edit_post',$id),'Anonymous cannot access appointment');$origin=new WP_REST_Request();$origin->set_header('origin','https://untrusted.example');check(is_wp_error(au_origin($origin)),'Cross-origin mutation rejected');
check(count(get_posts(array('numberposts'=>20,'post_status'=>'publish')))>=4,'Editable journal posts seeded');check(!in_array('18:15',au_slots('signature','ava',$date,0,60),true),'Original duration respected at closing');
echo 'TOTAL: '.$n." checks passed. Mail mocked; no external delivery.\n";$out=ob_get_clean();file_put_contents('/aurelia-tests/results.txt',$out);echo $out;
